import{_ as t,o as s,c as i,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0023 — Packaging quickstart : pip install teuthis-cms, API seule","description":"Extrait de docs/adr/0023-packaging-quickstart-teuthis-cms.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0023 — Packaging quickstart : pip install teuthis-cms, API seule","description":"Extrait de docs/adr/0023-packaging-quickstart-teuthis-cms.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0023-packaging-quickstart-teuthis-cms.md","filePath":"developpeurs/adr/0023-packaging-quickstart-teuthis-cms.md"}'),a={name:"developpeurs/adr/0023-packaging-quickstart-teuthis-cms.md"};function n(r,e,c,d,u,l){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="adr-0023--packaging-quickstart--pip-install-teuthis-cms-api-seule" tabindex="-1">ADR-0023 — Packaging quickstart : <code>pip install teuthis-cms</code>, API seule <a class="header-anchor" href="#adr-0023--packaging-quickstart--pip-install-teuthis-cms-api-seule" aria-label="Permalink to &quot;ADR-0023 — Packaging quickstart : \`pip install teuthis-cms\`, API seule {#adr-0023--packaging-quickstart--pip-install-teuthis-cms-api-seule}&quot;">​</a></h1><p><strong>Date :</strong> 28 août 2026 <strong>Statut :</strong> Accepté avec garde-fou <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> décision de fond actée le 19 août 2026 (Postgres via Docker orchestré par la CLI, périmètre API seule, séquencement après E6/E7) ; confirmée et affinée le 28 août 2026, une fois E1 à E15 livrés <strong>Renvois ultérieurs :</strong> prolongée par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a> (24 septembre 2026 : <code>pip install teuthis-cms</code> reste le chemin d&#39;essai ; le déploiement de production passe par des images, une pile et un installateur).</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le Core s&#39;installe aujourd&#39;hui de deux façons : <code>docker compose up</code> à la racine du repo (contributeur, ou essai du monorepo complet), ou une installation manuelle <code>pip install -e &quot;.[dev]&quot;</code> dans <code>apps/api</code> suivie d&#39;<code>alembic upgrade head</code> (README, section « Tests et migrations »). Les deux supposent d&#39;avoir cloné le dépôt. Aucune des deux ne couvre le geste d&#39;un tiers qui veut simplement essayer le Core sans contribuer au projet.</p><p>L&#39;arbitrage du 19 août avait posé trois bornes, avant que l&#39;admin Nuxt existe :</p><ol><li>Postgres via Docker, orchestré par la CLI — pas de SQLite, le Core dépend de JSONB/pgvector/FTS <code>french</code>+<code>unaccent</code> dès E1.</li><li>Périmètre API seule pour la première itération — <code>apps/admin</code> était alors un scaffold vide.</li><li>Séquencement après E6 (RBAC) et E7 (Plugin SDK) — un quickstart public avant l&#39;existence du RBAC aurait laissé n&#39;importe qui démarrer un CMS sans authentification.</li></ol><p>Les trois epics bloquants sont livrés depuis longtemps, et l&#39;admin Nuxt couvre désormais les 15 epics (50 pages, 68 composants) — la raison d&#39;exclure l&#39;admin en 2026-08-19 (« faute d&#39;admin à embarquer ») n&#39;existe plus. Reconfirmé le 28/08 : le périmètre reste <strong>API seule</strong> pour cette version — l&#39;admin tourne déjà en développement via <code>docker compose up</code>, et l&#39;embarquer dans un paquet pip est un chantier distinct (build de production Nuxt, mode de service, etc.) qui n&#39;a pas à peser sur celui-ci.</p><p>Aucun code, ADR ou entrée de backlog n&#39;existait pour ce chantier avant ce jour.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong><code>apps/api</code> devient un paquet pip installable sous le nom de distribution <code>teuthis-cms</code></strong>, exposant une commande <code>teuthiscms</code> qui scaffolde un nouveau projet, et un <code>manage.py</code> généré dans ce projet qui le démarre — modèle direct de <code>django-admin</code> / <code>manage.py</code> de Django, choisi précisément pour sa familiarité :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">pip</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> install</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis-cms</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">teuthiscms</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> mysite</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;">cd</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> mysite</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">python</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -m</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> manage</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> runserver</span></span></code></pre></div><p>Quatre décisions structurent l&#39;implémentation :</p><p><strong>1. Le module Python interne reste <code>app</code>, non renommé.</strong> Le paquet <code>app</code> (déjà utilisé dans une centaine de fichiers) devient, une fois installé, un module de premier niveau dans le site-packages de l&#39;utilisateur — un nom générique qui pourrait entrer en collision avec un autre paquet PyPI se nommant aussi <code>app</code>. Le risque est jugé faible (un utilisateur type installe <code>teuthis-cms</code> dans un environnement virtuel dédié à son projet, exactement comme Django le recommande pour les siens) et le coût d&#39;un renommage (~100 fichiers, aucune valeur fonctionnelle) sans rapport avec ce chantier. Un renommage futur vers un nom moins générique reste possible sans rupture de cette ADR.</p><p><strong>2. <code>teuthiscms</code> et <code>manage.py runserver</code> partagent la même logique de provisionnement</strong>, jamais dupliquée : assurer qu&#39;un conteneur Postgres nommé <code>teuthis-&lt;projet&gt;-postgres</code> (image <code>pgvector/pgvector:pg16</code>, identique à <code>docker-compose.yml</code>) existe et tourne, puis appliquer les migrations. <code>teuthiscms &lt;projet&gt;</code> l&#39;exécute une première fois pour livrer un projet immédiatement utilisable ; <code>manage.py runserver</code> la rejoue à chaque démarrage — redémarre le conteneur s&#39;il est arrêté, le recrée s&#39;il a disparu (auto-réparateur, jamais un échec sur un état qui se corrige seul). L&#39;orchestration passe par la commande <code>docker</code> en sous-processus, pas par le SDK Python <code>docker</code> : zéro dépendance nouvelle, cohérent avec la manière dont le projet justifie chaque ajout de dépendance (cf. <code>pyyaml</code> à l&#39;Epic E8).</p><p><strong>3. Les migrations restent une étape explicite et idempotente, jamais un hook de démarrage caché.</strong> <code>apps/api/alembic/</code> est embarqué dans le wheel (<code>force-include</code> du build hatchling, sans déplacer le répertoire dans le dépôt) et invoqué par l&#39;API Python d&#39;Alembic (<code>Config</code> + <code>command.upgrade</code>, <code>script_location</code> résolu via <code>importlib.resources</code>, <code>sqlalchemy.url</code> posé depuis <code>Settings.database_url</code>) plutôt que par un <code>alembic.ini</code> livré dans le projet scaffoldé — le projet de l&#39;utilisateur n&#39;a pas vocation à contenir ses propres migrations en v1. C&#39;est le même régime que <code>docker-compose.yml</code> (<code>alembic upgrade head &amp;&amp; uvicorn ...</code>), reproduit fidèlement plutôt que réinventé.</p><p><strong>4. Une installation neuve n&#39;expose rien qu&#39;elle n&#39;ait explicitement configuré.</strong> Les identifiants Postgres par défaut (<code>teuthis</code>/<code>teuthis</code>/<code>teuthis</code>) reprennent ceux, déjà publics, de <code>docker-compose.yml</code> — un choix de commodité pour un usage local, jamais présenté comme sûr pour autre chose. Le <code>README.md</code> généré dans le projet le dit en toutes lettres. Aucun autre réglage n&#39;est pré-rempli : <code>scheduler_token</code>, <code>captcha_provider</code> et tous les <code>AI_*</code> restent vides par défaut (ADR-0015 et pratique constante du Core), donc désactivés, exactement comme sur toute autre installation.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>SQLite par défaut, Postgres en option</strong></td><td>Écartée dès le 19/08 : JSONB, <code>pgvector</code> et la configuration FTS <code>french</code>+<code>unaccent</code> sont des dépendances structurelles depuis E1, pas des optimisations. Un mode SQLite serait un second backend à maintenir, avec des divergences de comportement difficiles à détecter avant la production.</td></tr><tr><td><strong>Renommer le module <code>app</code> en <code>teuthis_cms</code> dans le même chantier</strong></td><td>Écartée : ~100 fichiers à toucher pour un bénéfice cosmétique, sans rapport avec l&#39;objectif (rendre le Core installable). Repoussée à un chantier dédié si le besoin se confirme.</td></tr><tr><td><strong>SDK Python <code>docker</code> plutôt que sous-processus <code>docker</code></strong></td><td>Écartée : une dépendance de plus, pour un besoin (créer/démarrer/inspecter un conteneur nommé) que trois appels <code>subprocess</code> couvrent entièrement et plus lisiblement.</td></tr><tr><td><strong><code>alembic.ini</code> + dossier <code>alembic/</code> copiés dans le projet scaffoldé</strong></td><td>Écartée pour cette version : ferait croire que le projet peut porter ses propres migrations, ce qui n&#39;est pas le périmètre (pas de Content Type ni de plugin custom prévu en v1 du quickstart). Le mécanisme reste ouvrable plus tard sans rupture.</td></tr><tr><td><strong>Embarquer l&#39;admin Nuxt dans le paquet (build statique servi par l&#39;API)</strong></td><td>Écartée, reconfirmée le 28/08 malgré l&#39;admin désormais complet : un build de production Nuxt et son mode de service sont un chantier à part entière, pas une extension mécanique de celui-ci.</td></tr><tr><td><strong>Détection automatique d&#39;un port Postgres libre</strong></td><td>Écartée pour cette version : ajoute une branche de comportement implicite pour un besoin rare (plusieurs projets <code>teuthiscms</code> simultanés sur un même poste) ; un message d&#39;erreur explicite avec <code>--db-port</code> en réponse est plus prévisible.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un tiers qui veut essayer le Core n&#39;a plus besoin de cloner le dépôt.</li><li>Aucune divergence de comportement avec <code>docker compose up</code> : même image Postgres, même séquence de migration.</li><li>Le module <code>app</code> partagé entre le monorepo et le paquet distribué signifie qu&#39;aucun code applicatif ne diffère entre les deux chemins d&#39;installation — un correctif de sécurité (cf. le jeton d&#39;ordonnanceur des routes système) profite aux deux sans travail supplémentaire.</li></ul><p><strong>Négatives</strong></p><ul><li>Docker reste une dépendance d&#39;exploitation obligatoire, y compris pour un essai local — assumé au même titre que pour <code>docker compose up</code> aujourd&#39;hui.</li><li>Le module <code>app</code>, une fois installé, occupe un nom de premier niveau générique dans l&#39;environnement virtuel de l&#39;utilisateur — risque de collision faible mais réel avec un paquet tiers portant le même nom.</li><li>Un projet scaffoldé ne peut pas, en l&#39;état, porter ses propres migrations — toute extension du schéma applicatif reste un geste sur le Core lui-même, pas sur le projet de l&#39;utilisateur.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Publication effective sur PyPI (hors périmètre technique de cette ADR — dépend d&#39;une décision de diffusion, pas encore prise). → <strong>Close</strong> par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0024-rebranding-teuthis-cms-et-publication-pypi">ADR-0024</a> : <code>teuthis-cms</code> 0.1.0 publié sur PyPI le 29/08/2026, installation vérifiée dans un environnement neuf.</li><li>[ ] Réévaluer l&#39;inclusion de l&#39;admin Nuxt dans le paquet une fois qu&#39;un mode de build/service de production existe pour <code>apps/admin</code>.</li></ul>`,25)])])}const h=t(a,[["render",n]]);export{m as __pageData,h as default};
